#include <bits/stdc++.h>
using namespace std;

const int MAXN = 20;
const int MAXV = 2 * MAXN * MAXN;
const int INF = 0x3f3f3f3f;

char A[MAXN][MAXN], B[MAXN][MAXN];
int zombieDist[MAXN][MAXN];
int N, limitT;
const int mvx[] = {1,0,-1,0};
const int mvy[] = {0,1,0,-1};

inline bool passable(char c) { return c >= '0' && c <= '9'; }
inline bool positiveDigit(char c) { return c >= '1' && c <= '9'; }

struct DinicFlow {
    vector<int> adj[MAXV];
    int cap[MAXV][MAXV];
    int level[MAXV];
    int ptr[MAXV];

    DinicFlow() { memset(cap, 0, sizeof(cap)); }

    void addEdge(int u, int v, int c) {
        adj[u].push_back(v);
        adj[v].push_back(u);
        cap[u][v] = c;
        cap[v][u] = 0;
    }

    bool bfs(int s, int t) {
        memset(level, -1, sizeof(level));
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (int v : adj[u]) {
                if (cap[u][v] > 0 && level[v] == -1) {
                    level[v] = level[u] + 1;
                    q.push(v);
                }
            }
        }
        return level[t] != -1;
    }

    int dfs(int u, int t, int flow) {
        if (u == t) return flow;
        for (int &i = ptr[u]; i < (int)adj[u].size(); ++i) {
            int v = adj[u][i];
            if (cap[u][v] > 0 && level[v] == level[u] + 1) {
                int pushed = dfs(v, t, min(flow, cap[u][v]));
                if (pushed > 0) {
                    cap[u][v] -= pushed;
                    cap[v][u] += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    int maxFlow(int s, int t) {
        int ans = 0;
        while (bfs(s, t)) {
            memset(ptr, 0, sizeof(ptr));
            int pushed;
            while ((pushed = dfs(s, t, INF)) > 0) ans += pushed;
        }
        return ans;
    }
};

DinicFlow net;

void zombieBfs(int sx, int sy) {
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            zombieDist[i][j] = INF;
    zombieDist[sx][sy] = 0;
    queue<pair<int,int>> q;
    q.push({sx, sy});
    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + mvx[d], ny = y + mvy[d];
            if (nx < 0 || nx >= N || ny < 0 || ny >= N) continue;
            if (passable(A[nx][ny]) && zombieDist[nx][ny] == INF) {
                zombieDist[nx][ny] = zombieDist[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
}

void sourceEdgeBuilder(int sx, int sy) {
    int distArr[MAXN][MAXN];
    memset(distArr, INF, sizeof(distArr));
    distArr[sx][sy] = 0;

    if (positiveDigit(B[sx][sy]))
        net.addEdge(N * sx + sy, N * N + N * sx + sy, INF);

    queue<pair<int,int>> q;
    q.push({sx, sy});
    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + mvx[k], ny = y + mvy[k];
            if (nx < 0 || nx >= N || ny < 0 || ny >= N) continue;
            if (distArr[nx][ny] != INF) continue;
            if (!passable(A[nx][ny])) continue;

            int arrive = distArr[x][y] + 1;
            if (arrive <= min(zombieDist[nx][ny] - 1, limitT)) {
                distArr[nx][ny] = arrive;
                q.push({nx, ny});
            }
            if (arrive <= min(zombieDist[nx][ny], limitT) && positiveDigit(B[nx][ny]))
                net.addEdge(N * sx + sy, N * N + N * nx + ny, INF);
        }
    }
}

int main() {
    scanf("%d%d", &N, &limitT);
    int zx = 0, zy = 0;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            scanf(" %c", &A[i][j]);
            if (A[i][j] == 'Z') {
                zx = i; zy = j;
            } else if (positiveDigit(A[i][j])) {
                net.addEdge(MAXV - 2, i * N + j, A[i][j] - '0');
            }
        }
    }

    zombieBfs(zx, zy);

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            scanf(" %c", &B[i][j]);
            if (positiveDigit(B[i][j]))
                net.addEdge(N * N + i * N + j, MAXV - 1, B[i][j] - '0');
        }
    }

    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (positiveDigit(A[i][j])) sourceEdgeBuilder(i, j);

    printf("%d\n", net.maxFlow(MAXV - 2, MAXV - 1));
    return 0;
}
